"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[2565],{8687(e){e.exports=JSON.parse('{"tag":{"label":"Backtracking","permalink":"/concepts/tags/backtracking","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"state-space-search-and-optimization/backtracking","title":"Backtracking","description":"Some problems resist every technique seen so far. There is no greedy criterion that guarantees the optimum, the problem does not split into independent halves, and there is no small table of subproblems to fill. Very often the only way to be sure of the answer is to examine the candidate solutions one by one. Backtracking is the paradigm that organizes that examination so that it is systematic (no candidate is forgotten) and as cheap as possible (whole families of candidates are discarded at once).","permalink":"/concepts/state-space-search-and-optimization/backtracking"},{"id":"state-space-search-and-optimization/backtracking-examples","title":"Backtracking: Classic Problems","description":"This lesson applies the general schemes of backtracking to a series of classic problems. They are ordered from simple to more demanding, and each one illustrates a different aspect of the paradigm:","permalink":"/concepts/state-space-search-and-optimization/backtracking-examples"}],"unlisted":false}}')}}]);